{
  "lines": [
    {
      "text": "Leipzig d. 21. August 1786"
    },
    {
      "text": "Durchlauchtigster Herr Rolf!"
    },
    {
      "text": "Ew. Wohlgeboren Schreiben vom 3ten dießes habe ich in Leipzig richtig erhalten. Die Krüge aͤuß"
    },
    {
      "text": "Linzlau sind wohl verpackt und gehen mit dem Schiffen Hinrichs nach Berlin ab, wo sie Ende deß"
    },
    {
      "text": "Monats eintreffen sollen."
    },
    {
      "text": "Daß die Karte von Oßlaun betrifft, so ist der Ließänder Korn in Linzlau beinna unse"
    },
    {
      "text": "porrölfig; ist aber in Leipzig bey Lautkopf ein Exemplar gefun, daβ er für eine Thaler"
    },
    {
      "text": "ablößt."
    },
    {
      "text": "Mit vollkommener Hochachtung verharre ich"
    },
    {
      "text": "Ew. Wohlgeboren ergebenster Diener"
    },
    {
      "text": "J. G. Lehmann."
    }
  ],
  "script": "kurrent",
  "notes": "Handwritten in Kurrent script. Some letters are faint or slightly smudged, especially in the middle paragraph. 'aͤuß' has a superscript e-umlaut. 'daβ' uses the eszett. Signature at bottom."
}

